from typing import List, Dict

class Item:
    def __init__(self, name: str, price: float, qty: int):
        self.name = name
        self.price = price
        self.qty = qty

class DiscountCode:
    DISCOUNT_RATES = {
        'SAVE10': 0.10,
        'SAVE20': 0.20,
        'HALFOFF': 0.50,
    }

    @classmethod
    def apply_discount(cls, subtotal: float):
        discount_code = cls.DISCOUNT_RATES.get(cart.discount_code)
        if discount_code:
            return subtotal * discount_code
        return 0

class Cart:
    def __init__(self):
        self.items: List[Item] = []
        self.discount_code = None

    def add_item(self, item: Item):
        self.items.append(item)

    @property
    def subtotal(self):
        total = 0
        for item in self.items:
            total += item.price * item.qty
        return total

    @property
    def discount(self):
        return DiscountCode.apply_discount(self.subtotal)

    @property
    def tax(self):
        return (self.subtotal - self.discount) * 0.08

    @property
    def total(self):
        return self.subtotal - self.discount + self.tax
